// Program.cs
using System;
using System.Threading.RateLimiting;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.AspNetCore.Http;

var builder = WebApplication.CreateBuilder(args);

// Register a named rate‑limiting policy for the quote endpoint.
builder.Services.AddRateLimiter(options =>
{
    // Return 429 Too Many Requests when the limit is exceeded.
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;

    // Policy "QuotePolicy" limits each client IP to 10 requests per minute.
    options.AddPolicy("QuotePolicy", context =>
    {
        var clientKey = context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
        // Partition the limiter per client IP.
        return RateLimiterPartition<string>.GetFixedWindowLimiter(clientKey, _ => new FixedWindowRateLimiterOptions
        {
            PermitLimit = 10,
            Window = TimeSpan.FromMinutes(1),
            QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
            QueueLimit = 0,
            AutoReplenishment = true
        });
    });
});

var app = builder.Build();

// Routing must come before the rate‑limiting middleware when using endpoint attributes.
app.UseRouting();
app.UseRateLimiter();

app.MapGet("/api/quote", [EnableRateLimiting("QuotePolicy")] (HttpContext ctx) =>
{
    // Simple static quote response.
    var quote = "To be, or not to be, that is the question.";
    return Results.Ok(new { quote });
}).WithName("GetQuote");

app.Run();
